-- T-150 (ADR-78, ADR-39): movement pattern of an exercise, data for the E13 coach.
-- Nullable: custom exercises may leave it empty; every catalogue row is filled below from the reviewed mapping
-- scripts/exercise-movement-patterns.csv (statements generated by scripts/generate-exercise-catalog.py --patterns-out).

create type public.movement_pattern as enum (
  'squat', 'hinge', 'lunge', 'horizontal_push', 'vertical_push', 'horizontal_pull', 'vertical_pull', 'carry',
  'core', 'isolation', 'cardio', 'other'
);

alter table public.exercises add column movement_pattern public.movement_pattern;

