-- Manual exercises: edit gains the movement pattern (null clears it). The old 5-argument signature is dropped;
-- old app versions that omit p_movement_pattern still resolve to this one through its default.
drop function public.update_custom_exercise(uuid, text, public.muscle_group, public.equipment, boolean);

create function public.update_custom_exercise(
  p_id uuid, p_name text, p_muscle_group public.muscle_group, p_equipment public.equipment, p_per_hand boolean,
  p_movement_pattern public.movement_pattern default null)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_rows int;
begin
  if char_length(v_name) < 1 or char_length(v_name) > 100 then
    raise exception 'name must be 1-100 characters' using errcode = '22023';
  end if;
  update public.exercises
     set name = v_name, muscle_group = p_muscle_group, equipment = p_equipment,
         per_hand = coalesce(p_per_hand, false), movement_pattern = p_movement_pattern
   where id = p_id and is_custom and created_by = (select auth.uid());
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'exercise not found' using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function public.update_custom_exercise(
  uuid, text, public.muscle_group, public.equipment, boolean, public.movement_pattern) from public, anon;
grant execute on function public.update_custom_exercise(
  uuid, text, public.muscle_group, public.equipment, boolean, public.movement_pattern) to authenticated;
